CREATE TABLE IF NOT EXISTS duranki_treasury_scope(id VARCHAR(200) PRIMARY KEY,tenant_id VARCHAR(200) NOT NULL,tenant_name TEXT NOT NULL,community_id VARCHAR(200) NOT NULL UNIQUE,community_name TEXT NOT NULL,UNIQUE(tenant_id,community_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS duranki_treasury_party(id VARCHAR(200) PRIMARY KEY,name TEXT NOT NULL,service_id VARCHAR(200) NOT NULL,beneficiary_reference TEXT NOT NULL,share_bps INT NOT NULL CHECK(share_bps BETWEEN 1 AND 10000)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS duranki_treasury_receipt(id VARCHAR(200) PRIMARY KEY,scope_id VARCHAR(200) NOT NULL,party_id VARCHAR(200) NOT NULL,user_id VARCHAR(200) NOT NULL,member_name TEXT NOT NULL,reference VARCHAR(200) NOT NULL UNIQUE,received_cents BIGINT NOT NULL CHECK(received_cents>0),payable_cents BIGINT NOT NULL CHECK(payable_cents>0 AND payable_cents<=received_cents),share_bps INT NOT NULL,received_on VARCHAR(40) NOT NULL,created_by VARCHAR(200) NOT NULL,created_at VARCHAR(40) NOT NULL,FOREIGN KEY(scope_id) REFERENCES duranki_treasury_scope(id),FOREIGN KEY(party_id) REFERENCES duranki_treasury_party(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS duranki_treasury_payment(id VARCHAR(200) PRIMARY KEY,party_id VARCHAR(200) NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN ('DRAFT','APPROVED','SETTLED','CANCELLED')),created_by VARCHAR(200) NOT NULL,approved_by VARCHAR(200),bank_reference VARCHAR(200) UNIQUE,settled_by VARCHAR(200),created_at VARCHAR(40) NOT NULL,settled_on VARCHAR(40),FOREIGN KEY(party_id) REFERENCES duranki_treasury_party(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS duranki_treasury_payment_line(receipt_id VARCHAR(200) PRIMARY KEY,payment_id VARCHAR(200) NOT NULL,FOREIGN KEY(receipt_id) REFERENCES duranki_treasury_receipt(id),FOREIGN KEY(payment_id) REFERENCES duranki_treasury_payment(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS duranki_treasury_staff(user_id VARCHAR(200) PRIMARY KEY,role VARCHAR(40) NOT NULL CHECK(role IN ('Treasury Operator','Treasury Approver')),password_hash TEXT NOT NULL,version VARCHAR(200) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS duranki_treasury_audit(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,actor VARCHAR(200) NOT NULL,action VARCHAR(100) NOT NULL,record_id VARCHAR(200) NOT NULL,created_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS duranki_treasury_migration(id INT PRIMARY KEY,source_sha256 CHAR(64) NOT NULL,counts_json LONGTEXT NOT NULL,migrated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
